query IntegrationStaging($where: IntegrationStagingWhereInput, $orderBy: [IntegrationStagingOrderByInput!], $first: Int, $after: String) {
  integrationStaging(
    where: $where
    orderBy: $orderBy
    first: $first
    after: $after
  ) {
    edges {
      node {
        number
        internalRecordReference
        externalRecordReference
        outboundRecordReference
        metadata
        request
        response
        integrationConfig {
          name
          integrationType {
            integrationName
          }
        }
        status {
          name
        }
        createdAt
        updatedAt
      }
    }
  }
}

